import 'package:flutter/material.dart';
void main()=>runApp(const IHLinkApp());
class IHLinkApp extends StatelessWidget{const IHLinkApp({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'IHLink Datasub',theme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xff596235)),scaffoldBackgroundColor:const Color(0xfff7f7f3),useMaterial3:true),home:const LoginPage());}
class LoginPage extends StatefulWidget{const LoginPage({super.key});@override State<LoginPage> createState()=>_LoginPageState();}class _LoginPageState extends State<LoginPage>{final email=TextEditingController(),password=TextEditingController();@override Widget build(BuildContext c)=>Scaffold(body:SafeArea(child:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:440),child:Card(child:Padding(padding:const EdgeInsets.all(24),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[const Text('IHLink Datasub',style:TextStyle(fontSize:26,fontWeight:FontWeight.w900)),const SizedBox(height:8),const Text('Data, airtime and bills in one secure wallet.'),const SizedBox(height:28),TextField(controller:email,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(labelText:'Email',border:OutlineInputBorder())),const SizedBox(height:14),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Password',border:OutlineInputBorder())),const SizedBox(height:18),FilledButton(onPressed:()=>Navigator.pushReplacement(c,MaterialPageRoute(builder:(_)=>const Shell())),child:const Padding(padding:EdgeInsets.all(14),child:Text('Sign in')))]))))))));}}
class Shell extends StatefulWidget{const Shell({super.key});@override State<Shell> createState()=>_ShellState();}class _ShellState extends State<Shell>{int i=0;final pages=const [HomePage(),ServicesPage(),WalletPage(),HistoryPage(),AccountPage()];@override Widget build(BuildContext c)=>Scaffold(body:pages[i],bottomNavigationBar:NavigationBar(selectedIndex:i,onDestinationSelected:(v)=>setState(()=>i=v),destinations:const [NavigationDestination(icon:Icon(Icons.home_outlined),selectedIcon:Icon(Icons.home),label:'Home'),NavigationDestination(icon:Icon(Icons.grid_view_outlined),label:'Services'),NavigationDestination(icon:Icon(Icons.account_balance_wallet_outlined),label:'Wallet'),NavigationDestination(icon:Icon(Icons.receipt_long_outlined),label:'History'),NavigationDestination(icon:Icon(Icons.person_outline),label:'Account')]));}
}
class HomePage extends StatelessWidget{const HomePage({super.key});@override Widget build(BuildContext c)=>SafeArea(child:ListView(padding:const EdgeInsets.all(18),children:[const Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Welcome back',style:TextStyle(color:Colors.black54)),Text('IHLink Customer',style:TextStyle(fontSize:22,fontWeight:FontWeight.w800))]),CircleAvatar(child:Icon(Icons.notifications_outlined))]),const SizedBox(height:18),Container(padding:const EdgeInsets.all(22),decoration:BoxDecoration(color:const Color(0xff2f3020),borderRadius:BorderRadius.circular(24)),child:const Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('AVAILABLE BALANCE',style:TextStyle(color:Colors.white70)),SizedBox(height:8),Text('₦0.00',style:TextStyle(color:Colors.white,fontSize:34,fontWeight:FontWeight.w900)),SizedBox(height:18),Row(children:[Expanded(child:FilledButton(onPressed:null,child:Text('Fund Wallet'))),SizedBox(width:10),Expanded(child:OutlinedButton(onPressed:null,child:Text('History')))])])),const SizedBox(height:24),const Text('Quick Services',style:TextStyle(fontSize:18,fontWeight:FontWeight.w800)),const SizedBox(height:12),const ServiceGrid()]));}
class ServiceGrid extends StatelessWidget{const ServiceGrid({super.key});@override Widget build(BuildContext c){final x=[(Icons.wifi,'Data'),(Icons.phone_android,'Airtime'),(Icons.tv,'Cable TV'),(Icons.bolt,'Electricity'),(Icons.school,'Exam PIN'),(Icons.swap_horiz,'Airtime to Cash')];return GridView.count(crossAxisCount:3,shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),mainAxisSpacing:10,crossAxisSpacing:10,children:x.map((e)=>Card(child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(e.$1,color:const Color(0xff596235)),const SizedBox(height:8),Text(e.$2,textAlign:TextAlign.center,style:const TextStyle(fontWeight:FontWeight.w700))]))).toList());}}
class ServicesPage extends StatelessWidget{const ServicesPage({super.key});@override Widget build(BuildContext c)=>const SafeArea(child:Padding(padding:EdgeInsets.all(18),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Services',style:TextStyle(fontSize:26,fontWeight:FontWeight.w900)),SizedBox(height:18),ServiceGrid()])));}
class WalletPage extends StatelessWidget{const WalletPage({super.key});@override Widget build(BuildContext c)=>const BasicPage(title:'Wallet',icon:Icons.account_balance_wallet_outlined,text:'Fund your wallet, review credits and debits, and manage payment methods.');}class HistoryPage extends StatelessWidget{const HistoryPage({super.key});@override Widget build(BuildContext c)=>const BasicPage(title:'Transaction History',icon:Icons.receipt_long_outlined,text:'Your data, airtime, bill and wallet transactions will appear here.');}class AccountPage extends StatelessWidget{const AccountPage({super.key});@override Widget build(BuildContext c)=>const BasicPage(title:'Account',icon:Icons.person_outline,text:'Profile, security, transaction PIN, biometric unlock and support.');}
